  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wswakeband__pus wswakeband__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
